package com.pharmapack.qms.aql; import com.pharmapack.qms.batch.Batch; import jakarta.persistence.*; import lombok.*; import java.time.*; @Entity @Table(name="aql_inspections") @Getter @Setter @NoArgsConstructor public class AqlInspection { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="batch_id") Batch batch; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="aql_plan_id") AqlPlan aqlPlan; Long inspectorId; LocalDateTime inspectionTime; Integer sampleSize; Integer defectsFound=0; String result="PENDING"; String remarks; }
